import { render, screen, userEvent } from '@testing-library/react-native';
import { EditNameForm } from './EditNameForm';
import { saveName } from './api';

jest.mock('./api');

test('shows a confirmation after saving', async () => {
  jest.mocked(saveName).mockResolvedValue({ ok: true });
  const user = userEvent.setup();
  render(<EditNameForm initialName="An" />);

  await user.type(screen.getByLabelText('Name'), ' Nguyen');
  await user.press(screen.getByRole('button', { name: 'Save' }));

  expect(screen.getByText('Saved')).toBeOnTheScreen();
});

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { render, screen } from '@testing-library/react-native';
import { OrdersScreen } from './OrdersScreen';
import { fetchOrders } from './api';
jest.mock('./api');

const queryClient = new QueryClient();

function renderScreen() {
  return render(
    <QueryClientProvider client={queryClient}>
      <OrdersScreen />
    </QueryClientProvider>,
  );
}
test('shows an error when loading fails', async () => {
  jest.mocked(fetchOrders).mockRejectedValue(new Error('500'));
  renderScreen();
  expect(await screen.findByText('Could not load orders')).toBeOnTheScreen();
});

import { render, screen, userEvent } from '@testing-library/react-native';
import { ProfileScreen } from './ProfileScreen';

const mockNavigate = jest.fn();

jest.mock('@react-navigation/native', () => ({ useNavigation: () => ({ navigate: mockNavigate }) }));

test('opens settings from the profile screen', async () => {
  const user = userEvent.setup();
  render(<ProfileScreen />);

  await user.press(screen.getByRole('button', { name: 'Settings' }));

  expect(mockNavigate).toHaveBeenCalledWith('Settings');
});
